import { Component, signal } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { Router, RouterLink } from '@angular/router';
import { AuthService } from '../../services/auth.service';

@Component({
  selector: 'app-registro-usuario',
  standalone: true,
  imports: [CommonModule, FormsModule, RouterLink],
  templateUrl: './registro-usuario.component.html',
  styleUrl: './registro-usuario.component.css'
})
export class RegistroUsuarioComponent {
  nombre = '';
  apellidos = '';
  correo = '';
  password = '';
  telefono = '';
  departamento = '';
  ciudad = '';
  genero: 'Masculino' | 'Femenino' | 'Otro' = 'Masculino';
  fechaNacimiento = '';
  direccion = '';
  permiteUbicacion = false;

  cargando = signal(false);
  error = signal<string | null>(null);

  constructor(private auth: AuthService, private router: Router) {}

  crearCuenta() {
    if (!this.nombre || !this.apellidos || !this.correo || !this.password) {
      this.error.set('Completa al menos nombre, apellidos, correo y contraseña.');
      return;
    }
    this.error.set(null);
    this.cargando.set(true);

    this.auth.registro({
      nombre: this.nombre,
      correo: this.correo,
      password: this.password,
      rol: 'CLIENTE',
      apellidos: this.apellidos,
      telefono: this.telefono,
      departamento: this.departamento,
      ciudad: this.ciudad,
      genero: this.genero,
      fechaNacimiento: this.fechaNacimiento,
      direccion: this.direccion,
      permiteUbicacion: this.permiteUbicacion,
    }).subscribe({
      next: () => {
        this.cargando.set(false);
        this.router.navigate(['/agendar']);
      },
      error: err => {
        this.cargando.set(false);
        this.error.set(err?.error ?? 'No se pudo crear la cuenta.');
      }
    });
  }

  continuarConGoogle() {
    this.error.set('El acceso con Google se conectará próximamente. Regístrate con tu correo por ahora.');
  }

  continuarConFacebook() {
    this.error.set('El acceso con Facebook se conectará próximamente. Regístrate con tu correo por ahora.');
  }
}
<div class="kutt-reg-shell">
  <div class="kutt-reg-card">
    <a routerLink="/login" class="kutt-back">← Volver</a>
    <h2>Registro de Usuario</h2>

    <button class="kutt-btn-outline" (click)="continuarConGoogle()">Continuar con Google</button>
    <button class="kutt-btn-outline" (click)="continuarConFacebook()">Continuar con Facebook</button>
    <div class="kutt-divider"><span>o regístrate con tu correo</span></div>

    <div class="kutt-field"><label>Nombre</label><input [(ngModel)]="nombre" name="nombre"></div>
    <div class="kutt-field"><label>Apellidos</label><input [(ngModel)]="apellidos" name="apellidos"></div>
    <div class="kutt-field"><label>Correo electrónico</label><input type="email" [(ngModel)]="correo" name="correo"></div>
    <div class="kutt-field"><label>Contraseña</label><input type="password" [(ngModel)]="password" name="password"></div>
    <div class="kutt-field"><label>Teléfono</label><input [(ngModel)]="telefono" name="telefono"></div>
    <div class="kutt-field"><label>Departamento</label><input [(ngModel)]="departamento" name="departamento"></div>
    <div class="kutt-field"><label>Ciudad</label><input [(ngModel)]="ciudad" name="ciudad"></div>

    <div class="kutt-field">
      <label>Género</label>
      <div class="kutt-genero-row">
        <label class="kutt-radio"><input type="radio" name="genero" value="Masculino" [(ngModel)]="genero"> Masculino</label>
        <label class="kutt-radio"><input type="radio" name="genero" value="Femenino" [(ngModel)]="genero"> Femenino</label>
        <label class="kutt-radio"><input type="radio" name="genero" value="Otro" [(ngModel)]="genero"> Otro</label>
      </div>
    </div>

    <div class="kutt-field"><label>Fecha de nacimiento</label><input type="date" [(ngModel)]="fechaNacimiento" name="fechaNacimiento"></div>
    <div class="kutt-field"><label>Dirección (opcional)</label><input [(ngModel)]="direccion" name="direccion"></div>

    <label class="kutt-checkbox">
      <input type="checkbox" [(ngModel)]="permiteUbicacion" name="permiteUbicacion">
      Permite el uso de tu ubicación para encontrar negocios cercanos
    </label>

    <p class="kutt-error" *ngIf="error()">{{ error() }}</p>

    <button class="kutt-btn-primary" [disabled]="cargando()" (click)="crearCuenta()">
      {{ cargando() ? 'Creando cuenta...' : 'Crear cuenta' }}
    </button>

    <p class="kutt-switch">¿Ya tienes cuenta? <a routerLink="/login">Inicia sesión</a></p>
  </div>
</div>
